OUT = '/results'

# src/util-classification-config.c:42 DETECT_CLASSCONFIG_REGEX
CLASS_RE = re.compile(
    rb'^\s*config\s*classification\s*:\s*([a-zA-Z][a-zA-Z0-9-_]*)\s*,\s*(.+)\s*,\s*(\d+)\s*$')

NAME_MAX = 64   # CLASSTYPE_NAME_MAX_LEN
DESC_MAX = 512  # CLASSTYPE_DESC_MAX_LEN
FGETS_BUF = 1024


def fgets_lines(path):
    """Yield chunks exactly as fgets(line, 1024, fd) would return them."""
    data = open(path, 'rb').read()
    i = 0
    n = len(data)
    while i < n:
        j = data.find(b'\n', i)
        if j == -1:
            end = min(i + FGETS_BUF - 1, n)
        else:
            end = min(j + 1, i + FGETS_BUF - 1)
        yield data[i:end]
        i = end


def is_blank_or_comment(line):
    """SCClassConfIsLineBlankOrComment()"""
    for c in line:
        if c == 0x23:  # '#'
            return True
        if not chr(c).isspace() or c > 0x7F:
            # isspace() on ASCII set: ' ', \t, \n, \v, \f, \r
            if bytes([c]) not in b' \t\n\v\f\r':
                return False
        if bytes([c]) not in b' \t\n\v\f\r':
            return False
    return True


def load_classtypes():
    stored = {}   # lowercased name -> dict
    order = []
    i = 1         # SCClassConfParseFile: uint16_t i = 1
    errors = 0
    for line in fgets_lines(CONF):
        if is_blank_or_comment(line):
            continue
        m = CLASS_RE.match(line)
        if m is None:
            errors += 1
            continue
        name, desc, prio = m.group(1), m.group(2), m.group(3)
        # pcre2_substring_copy_bynumber needs substring + NUL to fit
        if len(name) + 1 > NAME_MAX or len(desc) + 1 > DESC_MAX:
            errors += 1
            continue
        try:
            priority = int(prio)
        except ValueError:
            errors += 1
            continue
        if priority > 0xFFFFFFFF:  # StringParseUint32 range check
            errors += 1
            continue
        key = bytes(bytearray(
            c + 32 if 0x41 <= c <= 0x5A else c for c in name))  # ASCII tolower
        if key not in stored:
            ct = {'id': i & 0xFFFF, 'name': key.decode('utf-8'),
                  'description': desc.decode('utf-8'), 'priority': priority}
            stored[key] = ct
            order.append(ct)
        i += 1
    return order, errors


def is_rule_line(raw):
    s = raw.strip()
    if not s:
        return False
    return not s.startswith(b'#')


def count_usage(names):
    pats = {n: re.compile(
        (r'classtype\s*:\s*' + re.escape(n) + r'\s*(?=;|$)').encode(),
        re.IGNORECASE) for n in names}
    counts = {n: 0 for n in names}
    files = {n: set() for n in names}
    for fn in sorted(os.listdir(RULES_DIR)):
        if not fn.endswith('.rules'):
            continue
        path = os.path.join(RULES_DIR, fn)
        for raw in open(path, 'rb').read().split(b'\n'):
            if not is_rule_line(raw):
                continue
            for n, pat in pats.items():
                if pat.search(raw):
                    counts[n] += 1
                    files[n].add(fn)
    return counts, files


def main():
    order, errors = load_classtypes()
    order.sort(key=lambda c: c['id'])
    names = [c['name'] for c in order]
    counts, files = count_usage(names)

    os.makedirs(OUT, exist_ok=True)
    idx = os.path.join(OUT, 'class-index')
    os.makedirs(idx, exist_ok=True)

    with open(os.path.join(OUT, 'classtypes.json'), 'w', encoding='utf-8') as f:
        f.write(json.dumps(order, separators=(',', ':'), ensure_ascii=False))
        f.write('\n')

    by_name = sorted(order, key=lambda c: c['name'].encode())
    with open(os.path.join(OUT, 'classtype-usage.csv'), 'w',
              encoding='utf-8', newline='') as f:
        f.write('name,priority,rule_count,files\n')
        for c in by_name:
            n = c['name']
            fl = ';'.join(sorted(files[n]))
            f.write(f'{n},{c["priority"]},{counts[n]},{fl}\n')

    with open(os.path.join(OUT, 'unused.txt'), 'w',
              encoding='utf-8', newline='') as f:
        for c in by_name:
            if counts[c['name']] == 0:
                f.write(c['name'] + '\n')

    for c in order:
        with open(os.path.join(idx, f'{c["id"]}.txt'), 'w',
                  encoding='utf-8', newline='') as f:
            f.write(f'{c["name"]}\n{c["priority"]}\n')

    print(f'stored={len(order)} parse_errors={errors} '
          f'max_id={order[-1]["id"]} used={sum(1 for c in order if counts[c["name"]])}')


if __name__ == '__main__':
    main()
